"""Write an honest, separate recovery report; never changes app, weights or slides."""
import argparse,json,hashlib
from pathlib import Path
import xml.etree.ElementTree as ET
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from scripts.recall_recovery_common import vector,feasibility,CLASSES,TARGETS
ROOT=Path(__file__).resolve().parents[1]
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--run-dir',default='reports/pure_recall_recovery_v2_20261108');a=ap.parse_args();run=ROOT/a.run_dir
 decision=read(run/'deployment_decision.json');head=read(run/'head_history.json');full=read(run/'full_history.json');current=read(run/'current_validation.json');earlier=read(run/'earlier_validation.json')
 protected={name:{'expected':h,'actual':sha(ROOT/name)} for name,h in read(run/'protected_artifacts.json').items()};unchanged=all(x['expected']==x['actual'] for x in protected.values())
 lines=['# Pure FusDenseNet class-recall recovery experiment','', 'Completed 8 November 2026. This report records a new experiment separately from the deployed model.','',f"Deployment gate passed: **{decision['eligible']}**. New test evaluated: **{decision['test_evaluated']}**. App/model/PPT protected hashes unchanged: **{unchanged}**.",'',decision['reason'],'','## Actual validation results','', 'Every row below uses all 3,970 retained validation faces, including all 50 disgust examples. Classifier rows are the best feasibility score within each recipe, not test results. Feasibility is a selection penalty, not a model-quality metric.','', '| Stage | Completed epochs | Accuracy | Macro F1 | Disgust P/R/F1 | Happy recall | Surprise recall | Neutral recall | Meets all gates |','|---|---:|---:|---:|---|---:|---:|---:|---|']
 def table(name,n,r,ok):
  c=r['classification_report'];v=vector(r);return f"| {name} | {n} | {r['accuracy']:.2%} | {v['macro_f1']:.4f} | {v['disgust_precision']:.4f}/{v['disgust_recall']:.2%}/{v['disgust_f1']:.4f} | {c['happy']['recall']:.2%} | {c['surprise']['recall']:.2%} | {c['neutral']['recall']:.2%} | {ok} |"
 lines.append(table('Deployed pure baseline','â€”',current,'baseline'))
 for recipe in read(run/'protocol.json')['recipes']:
  rows=[r for r in head if r['recipe']==recipe['name']];best=max(rows,key=lambda r:r['feasibility_objective']);ep=best['epoch']-max(x['epoch'] for x in read(run/'initial_history.json'));r=read(run/recipe['name']/f"validation_{ep:02d}_{best['kind']}.json");lines.append(table(recipe['name'],len(rows),r,best['eligible']))
 for i,row in enumerate(full,1):lines.append(table(f"Full network epoch {i} ({row['kind']})",1,read(run/f"full_validation_{i:02d}_{row['kind']}.json"),row['eligible']))
 lines+=['','## What changed and what failed','',f"The corrected run completed {len(head)} native-classifier epochs across four independent recipes, then {len(full)} full-network epochs. These are different workloads and are not counted as {len(head)+len(full)} full-network epochs.",'', 'The previous recovery attempt accidentally reduced total happy/surprise/neutral class cost when downweighting their mirrored views. The corrected factors are 2/(1+lambda) for raw and 2lambda/(1+lambda) for mirrored views; their sum is two. The earlier interrupted run completed 21 classifier-only epochs, with its partial next epoch discarded; it is preserved in reports/pure_recall_recovery_20261108 and produced no test candidate. These 21 epochs are separate from the 54 corrected classifier epochs. This implementation error is verified algebraically and by a unit test, but is not claimed to explain every generalization failure.','', 'Four native-head recipes increase the happy/surprise/neutral TRAIN loss cost and retain correct TRAIN disgust outputs from the same current pure classifier. The full-network stage also protects correct non-disgust examples through balanced disgust-vs-rest retention. Its deterministic retention branch bypasses classifier dropout; ordinary classification loss still uses dropout. This is TRAIN-only self-reference, not an external teacher or inference hybrid. All full-network emotion-path parameters can update; BatchNorm running statistics remain frozen. The reference is discarded for inference.','', 'Raising common-class costs can recover those classes by shifting decision boundaries while harming disgust precision or other classes. Every requested class and all disgust precision/recall/F1 metrics are checked separately. A higher accuracy alone does not qualify.','', 'TRAIN has 23,503 source images and only 330 disgust images, versus 6,039 happy images. Mirroring creates views, not new subjects. Validation has only 50 disgust cases. The spatial/attention backbone and small imbalanced data remain potential constraints; no isolated ablation here proves a single cause. Historical validation reuse and previously inspected test results limit independent confirmation.','', '## Test and deployment policy','', 'One eligible candidate may be frozen after validation. The full 6,561-face test must improve accuracy and macro F1, preserve macro precision/recall and disgust precision/recall/F1, and restore happy/surprise/neutral recall to at least 81.59%/73.84%/58.54%. No threshold, alternate test candidate, external encoder or inference ensemble is allowed.']
 audit=read(run/'baseline_train_orientation_audit.json')['results'];original=audit['original_train'];mirror=audit['mirrored_train']
 lines+=['', 'Measured generalization audit of the deployed pure checkpoint: original TRAIN accuracy '+format(original['accuracy'],'.2%')+', mirrored TRAIN accuracy '+format(mirror['accuracy'],'.2%')+', versus validation '+format(current['accuracy'],'.2%')+'. Disgust recall: original TRAIN '+format(original['classification_report']['disgust']['recall'],'.2%')+', mirrored TRAIN '+format(mirror['classification_report']['disgust']['recall'],'.2%')+', validation '+format(current['classification_report']['disgust']['recall'],'.2%')+'. This is evidence of a large generalization gap, not proof of a particular single cause. Scores use cached TRAIN logits from the same verified checkpoint.']
 if not decision['test_evaluated']:lines+=['','No new test accuracy, F1 or disgust recall is claimed: no validation candidate qualified. The deployed actual test metrics remain 58.34% accuracy, 0.5554 macro F1, and 46.84% disgust recall (37/79).']
 else:
  result=read(run/'deployment/reports/emotion_evaluation.json');lines+=['',table('Frozen candidate FULL TEST', 'â€”',result,decision['eligible']),'','This test row uses 6,561 faces; the validation rows above use 3,970.']
 lines+=['','## Reproducibility and verification','', 'Executed source snapshots, file hashes, protocols, every validation report, histories and decision JSON are retained in the run directory. Current checkpoint and PPT are not overwritten by this reporting script.','', '```powershell',r'.\.venv\Scripts\python.exe -m pytest -q',r'.\.venv\Scripts\python.exe -m scripts.report_recall_recovery --run-dir reports/pure_recall_recovery_v2_20261108','```','', 'The completed run is immutable; training scripts reject completed/frozen run directories. A new future run requires a separate directory and prospectively declared protocol.','', 'EEG/HRV results are unchanged. No new real physiological-fusion, weather-response, clinical benefit or raga-efficacy result is claimed. No user photograph was used for training or evaluation.']
 update_audit=read(run/'full_parameter_update_audit.json');lines+=['', 'A direct checkpoint comparison after '+str(update_audit['completed_full_epochs_at_audit'])+' full epoch(s) verified changes in '+str(update_audit['emotion_path_changed_tensors'])+' emotion-path parameter tensors, including '+str(update_audit['attention_changed_tensors'])+' attention tensors. This verifies feature-learning updates occurred; it does not establish that those updates improved held-out performance. Detailed relative changes are saved in full_parameter_update_audit.json.']
 tests=ROOT/'reports/recall_recovery_tests.xml'
 if tests.exists():
  suites=ET.parse(tests).getroot();nodes=[suites] if suites.tag=='testsuite' else list(suites);summary={k:sum(float(n.get(k,0)) for n in nodes) for k in ['tests','failures','errors','skipped','time']};lines+=['',f'Test suite: {summary}.'];(run/'test_summary.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')
 (ROOT/'PURE_RECALL_RECOVERY_RESULTS.md').write_text('\n'.join(lines)+'\n',encoding='utf-8');(run/'protected_artifacts_final_audit.json').write_text(json.dumps({'all_unchanged':unchanged,'files':protected},indent=2),encoding='utf-8')
 fig,axes=plt.subplots(2,3,figsize=(16,8));keys=['val_accuracy','val_macro_f1','val_disgust_recall','val_happy_recall','val_surprise_recall','val_neutral_recall'];titles=['Validation accuracy','Validation macro F1','Validation disgust recall','Validation happy recall','Validation surprise recall','Validation neutral recall'];c=current['classification_report'];base=[current['accuracy'],c['macro avg']['f1-score'],c['disgust']['recall'],c['happy']['recall'],c['surprise']['recall'],c['neutral']['recall']]
 for ax,key,title,b in zip(axes.flat,keys,titles,base):
  for recipe in read(run/'protocol.json')['recipes']:
   rows=[r for r in head if r['recipe']==recipe['name']];ax.plot(range(1,len(rows)+1),[r[key] for r in rows],label=recipe['name'])
  ax.axhline(b,color='black',linestyle='--',label='Deployed baseline');ax.set(title=title,xlabel='Classifier epoch within independent recipe');ax.grid(alpha=.2)
 axes[0,0].legend(fontsize=7);fig.suptitle('Actual validation curves â€” classifier recipes are independent; no test tuning');fig.tight_layout();fig.savefig(run/'head_validation_curves.png',dpi=140);plt.close(fig)
 fig,axes=plt.subplots(2,3,figsize=(14,7))
 for ax,key,title,b in zip(axes.flat,keys,titles,base):
  ax.plot(range(1,len(full)+1),[r[key] for r in full],marker='o',label='Full-network stage');ax.axhline(b,color='black',linestyle='--');ax.set(title=title,xlabel='Full-network epoch');ax.set_xticks(range(1,len(full)+1));ax.grid(alpha=.2)
 fig.suptitle('Actual validation curves â€” full-network stage only');fig.tight_layout();fig.savefig(run/'full_validation_curves.png',dpi=140);plt.close(fig)
 (run/'completion.json').write_text(json.dumps({'reported':True,'app_ppt_unchanged':unchanged,'decision':decision},indent=2),encoding='utf-8');print(json.dumps({'report':'PURE_RECALL_RECOVERY_RESULTS.md','protected_artifacts_unchanged':unchanged,'decision':decision},indent=2))
if __name__=='__main__':main()
